 1	final class RodCuttingSolver {
 2	    private final PriceTable priceTable;
 3	    private final RevenueTable revenueTable;
 4	    private final int rodLength;
 5	
 6	    RodCuttingSolver(PriceTable priceTable) {
 7	        this.priceTable = priceTable;
 8	        this.rodLength = priceTable.maxLength();
 9	        this.revenueTable = new RevenueTable(rodLength);
10	    }
11	
12	    int solve() {
13	        for (int currentLength = 1; currentLength <= rodLength; currentLength++) {
14	            revenueTable.recordBestRevenue(currentLength, computeBestRevenue(currentLength));
15	        }
16	
17	        return revenueTable.bestRevenueFor(rodLength);
18	    }
19	
20	    private int computeBestRevenue(int targetLength) {
21	        int bestRevenue = 0;
22	
23	        for (int firstCutLength = 1; firstCutLength <= targetLength; firstCutLength++) {
24	            bestRevenue = Math.max(
25	                    bestRevenue,
26	                    priceTable.priceFor(firstCutLength)
27	                            + revenueTable.bestRevenueFor(targetLength - firstCutLength)
28	            );
29	        }
30	
31	        return bestRevenue;
32	    }
33	}

